package android.graphics; public class Outline { private Rect rect=new Rect(); private float radius,alpha=1; public void setEmpty(){rect.setEmpty();} public boolean isEmpty(){return rect.isEmpty();} public void setRect(int l,int t,int r,int b){rect.set(l,t,r,b);radius=0;} public void setRect(Rect r){setRect(r.left,r.top,r.right,r.bottom);} public void setRoundRect(int l,int t,int r,int b,float radius){rect.set(l,t,r,b);this.radius=radius;} public void setRoundRect(Rect r,float radius){setRoundRect(r.left,r.top,r.right,r.bottom,radius);} public void setOval(int l,int t,int r,int b){setRoundRect(l,t,r,b,Math.min(r-l,b-t)/2f);} public void setOval(Rect r){setOval(r.left,r.top,r.right,r.bottom);} public void setConvexPath(Path p){RectF f=new RectF();p.computeBounds(f,true);setRect((int)f.left,(int)f.top,(int)f.right,(int)f.bottom);} public void setPath(Path p){setConvexPath(p);} public void setAlpha(float a){alpha=a;} public float getAlpha(){return alpha;} public boolean getRect(Rect r){r.set(rect);return !isEmpty();} public float getRadius(){return radius;} public boolean canClip(){return !isEmpty();} public void offset(int x,int y){rect.offset(x,y);} }